import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%AF%E3%83%AB%E3%82%AD%E3%83%A5%E3%83%BC%E3%83%AC%E3%81%AE%E4%BC%9D%E8%AA%AC.html","title":"ワルキューレの伝説","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.34,"words":101},"filePathRelative":"ワルキューレの伝説.md"}`),a={name:`ワルキューレの伝説.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="ワルキューレの伝説" tabindex="-1"><a class="header-anchor" href="#ワルキューレの伝説"><span>ワルキューレの伝説</span></a></h1><p>私が2026年現在最後にゲーセンでやってたゲームのうちの一つ。まだクリアしてないのでクリアしたい。</p><ul><li><a href="https://xneo.jp/valkyrie-no-densetsu/" target="_blank" rel="noopener noreferrer">ワルキューレの伝説完全攻略 - XNEO - ゲーム攻略・裏技情報サイト</a> 具体的な著者なりのパターンが参考になる</li><li><a href="http://web1.kcn.jp/kyoto/ValkyrieNoDensetsu/index.html" target="_blank" rel="noopener noreferrer">ワルキューレの伝説 攻略</a> マップなどより包括的な情報。</li></ul><p>Switchで900円くらいでAC版が買える。</p><h2 id="_2026-08-29-土" tabindex="-1"><a class="header-anchor" href="#_2026-08-29-土"><span>2026-08-29 (土)</span></a></h2><p>6面くらいまでは行けるようになった。5面はあまり死なないが結構食らうので5面を安定化するのが先か。</p><p>5面の爆弾と4wayの所のアイテム調整があまり上手くいかない。最近は4面の貫通はとらない方針にしている。貫通使いにくいし。</p><p>6面はまだまだマップを覚えていないが、宝箱やショップはいらないのも多いのでもう少し最短ルートにする方がいいかもしれない。</p>`,8)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};